import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import Icon from 'flarum/common/components/Icon';
import Button from 'flarum/common/components/Button';
import FormSection from 'flarum/admin/components/FormSection';
import FormSectionGroup from 'flarum/admin/components/FormSectionGroup';
import FieldEditModal from './FieldEditModal';
import sortFields from '../../common/utils/sortFields';
export default class MasqueradePage extends ExtensionPage {
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.store.all('masquerade-fields').length) {
      this.loading = true;
      app.store.find('masquerade-fields').finally(() => {
        this.loading = false;
        m.redraw();
      });
    }
  }
  sections(vnode) {
    const items = super.sections(vnode);
    items.setPriority('content', 20);
    items.add('fields', this.fieldsSection(), 10);
    return items;
  }
  fieldsSection() {
    return m(FormSectionGroup, {
      className: "MasqueradePage container"
    }, m(FormSection, {
      label: app.translator.trans('fof-masquerade.admin.fields.title')
    }, m("ol", {
      className: "MasqueradePage-list",
      oncreate: vnode => this.createSortable(vnode.dom),
      onremove: () => this.sortable?.destroy()
    }, sortFields(app.store.all('masquerade-fields')).map(field => m("li", {
      key: field.id(),
      "data-id": field.id(),
      className: "MasqueradeFieldListItem"
    }, field.icon() && m(Icon, {
      name: field.icon(),
      className: "MasqueradeFieldListItem-icon"
    }), m("span", {
      className: "MasqueradeFieldListItem-name"
    }, field.name()), m(Button, {
      "aria-label": app.translator.trans('fof-masquerade.admin.fields.edit', {
        field: field.name()
      }),
      className: "Button Button--link Button--icon MasqueradeFieldListItem-edit",
      icon: "fas fa-pencil-alt",
      onclick: () => app.modal.show(FieldEditModal, {
        model: field
      })
    })))), m(Button, {
      className: "Button Button--dashed",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(FieldEditModal)
    }, app.translator.trans('fof-masquerade.admin.buttons.add-field'))));
  }
  async createSortable(element) {
    const {
      default: sortableModule
    } = await flarum.reg.asyncModuleImport('flarum/admin/utils/loadSortable');
    if (!element.isConnected) return;
    this.sortable = sortableModule.create(element, {
      animation: 150,
      draggable: '.MasqueradeFieldListItem',
      filter: 'button',
      preventOnFilter: false,
      onEnd: ({
        oldIndex,
        newIndex
      }) => {
        if (oldIndex == null || newIndex == null || oldIndex === newIndex) return;
        const fields = sortFields(app.store.all('masquerade-fields'));
        // Restore the DOM order so Mithril can reconcile the keyed items.
        this.sortable.sort(fields.map(field => field.id()));
        const [movedField] = fields.splice(oldIndex, 1);
        fields.splice(newIndex, 0, movedField);
        const sorting = [];
        fields.forEach((field, index) => {
          field.pushAttributes({
            sort: index
          });
          sorting.push(Number(field.id()));
        });
        this.updateSort(sorting);
        m.redraw();
      }
    });
  }
  updateSort(sorting) {
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/masquerade-fields/order',
      body: {
        sort: sorting
      }
    });
  }
}
flarum.reg.add('fof-masquerade', 'admin/components/MasqueradePage', MasqueradePage);